      <li><strong>Agni‑III</strong> is the first Indian missile to cross the <strong>3 000 km** threshold, qualifying it as an IRBM.</li>
      <li>The <strong>Akash</strong> system can engage up to **four** targets simultaneously within a 30 km radius.</li>
      <li><strong>Trishul</strong> achieves a reaction time of **≤ 30 seconds** due to its vertical launch capability.</li>
      <li><strong>Nag</strong> can penetrate **800 mm RHA** and has a “fire‑and‑forget” laser guidance mode.</li>
      <li>All IGMDP missiles share a common <strong>modular warhead bay</strong> allowing quick swap between conventional and nuclear payloads.</li>
      <li>India’s strategic missile “Triad” (land‑, sea‑, and air‑launched) is realised through the combined deployment of **Prithvi‑III**, **Agni‑V**, and **Akash‑SAM**.</li>
    </ul>
